import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { assertNoSymlinks } from './sync-contract.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const owners = ['harness', 'ontology'];
const digest = bytes => createHash('sha256').update(bytes).digest('hex');

// Parent-only producer. Independent packages ship these exact generated bytes,
// so standalone CI and consumers do not fetch executable code from parent main.
export async function syncToolchain({ check = false } = {}) {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'evopilot-toolchain-build-'));
  try {
    const compiled = spawnSync(process.execPath, [path.join(root, 'node_modules/typescript/bin/tsc'), 'integration/toolchain/cli.ts', '--outDir', temporary, '--rootDir', 'integration', '--target', 'ES2023', '--module', 'NodeNext', '--strict', '--declaration', '--noEmitOnError'], { cwd: root, encoding: 'utf8' });
    if (compiled.error) throw compiled.error;
    if (compiled.status !== 0) throw Error(compiled.stdout + compiled.stderr);
    const files = new Map();
    for (const name of ['archive.js', 'archive.d.ts', 'locked.js', 'locked.d.ts', 'cli.js', 'cli.d.ts']) {
      const bytes = fs.readFileSync(path.join(temporary, 'toolchain', name), 'utf8').replaceAll('../compatibility/v1/native.mjs', '../native.mjs');
      files.set(name, Buffer.from(bytes));
    }
    const resources = ['toolchain.lock.json', 'requirements.lock', 'conftest-dependencies.json', 'opa-dependencies.json', ...fs.readdirSync(path.join(root, 'integration/toolchain/licenses')).map(n => 'licenses/' + n)];
    for (const name of resources) files.set(name, fs.readFileSync(path.join(root, 'integration/toolchain', name)));
    const manifest = { schema: 'evopilot-generated-toolchain/v1', producer: 'evopilot/scripts/sync-toolchain.mjs', sourceDigests: Object.fromEntries(['cli.ts', 'locked.ts', 'archive.ts'].map(n => [n, digest(fs.readFileSync(path.join(root, 'integration/toolchain', n)))])), files: [...files].map(([name, bytes]) => ({ path: name, sha256: digest(bytes) })).sort((a,b) => a.path.localeCompare(b.path, 'en')) };
    files.set('manifest.json', Buffer.from(JSON.stringify(manifest, null, 2) + '\n'));
    for (const owner of owners) for (const [name, bytes] of files) {
      const destination = path.join(root, 'projects/evopilot-' + owner, 'vendor/compatibility/v1/toolchain', name);
      await assertNoSymlinks(destination, !check);
      if (check) { if (!fs.readFileSync(destination).equals(bytes)) throw Error('Generated toolchain drift: ' + owner + '/' + name); }
      else { fs.mkdirSync(path.dirname(destination), { recursive: true }); fs.writeFileSync(destination, bytes, { mode: 0o644 }); }
    }
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try {
    const args = process.argv.slice(2);
    if (args.length > 1 || args.length && args[0] !== '--check') throw Error('Usage: sync-toolchain.mjs [--check]');
    await syncToolchain({ check: args[0] === '--check' });
    process.stdout.write(args[0] === '--check' ? 'Generated toolchains verified\n' : 'Generated toolchains synchronized\n');
  } catch (error) { process.stderr.write(error.message + '\n'); process.exitCode = 1; }
}
